let signup=false,busy=false;const $=id=>document.getElementById(id);
const accountPlans={entry:{name:'Entry',kind:'Pay-As-You-Go',price:'₹1,500 setup (one-time)',features:['Platform fee: ₹1,100/month','Usage: ₹6/minute','1 agent / 1 concurrent call','Additional agent or concurrency: ₹2,000/month each']},growth:{name:'Growth',kind:'Monthly Plan',price:'₹15,000/month',features:['Setup fee: ₹0','3,000 minutes included','Extra usage: ₹5/minute','3 agents / 3 concurrent calls','Additional agent or concurrency: ₹2,000/month each']},scale:{name:'Scale',kind:'Yearly Plan',price:'₹1,50,000/year',features:['Setup fee: ₹0','50,000 minutes included','Extra usage: ₹4/minute','4 agents / 4 concurrent calls','Additional agent or concurrency: ₹1,800/month each']},enterprise:{name:'Enterprise',kind:'Custom Plan',price:'Custom pricing',features:['Unlimited minutes','Unlimited concurrency','Custom AI workflows','Dedicated infrastructure and SLA']}};
function setMode(value){if(busy)return;signup=value;$('title').textContent=signup?'Create your account':'Welcome back';$('intro').textContent=signup?'Create an account for this shared voice assistant.':'Sign in to your voice assistant.';$('password').autocomplete=signup?'new-password':'current-password';$('confirmField').hidden=!signup;$('accountTypeField').hidden=!signup;$('accountPlanPanel').hidden=true;$('confirmPassword').required=signup;$('password').value='';$('confirmPassword').value='';$('submit').textContent=signup?'Create account':'Sign in';$('signInTab').className=signup?'quiet':'';$('signUpTab').className=signup?'':'quiet';$('signInTab').setAttribute('aria-pressed',String(!signup));$('signUpTab').setAttribute('aria-pressed',String(signup));$('feedback').textContent='';}
function selectAccountPlan(key){const plan=accountPlans[key];if(!plan)return;$('accountType').value=key;$('accountTypeSummary').textContent=plan.name;document.querySelector('.signup-account-type-menu').open=false;$('accountPlanKind').textContent=plan.kind;$('accountPlanName').textContent=plan.name;$('accountPlanPrice').textContent=plan.price;$('accountPlanFeatures').replaceChildren(...plan.features.map(text=>{const item=document.createElement('li');item.textContent=text;return item}));$('accountPlanPanel').hidden=false;$('closeAccountPlan').focus()}
$('signInTab').onclick=()=>setMode(false);$('signUpTab').onclick=()=>setMode(true);
document.querySelectorAll('[data-signup-plan]').forEach(button=>button.onclick=()=>selectAccountPlan(button.dataset.signupPlan));$('closeAccountPlan').onclick=()=>$('accountPlanPanel').hidden=true;document.addEventListener('keydown',event=>{if(event.key==='Escape')$('accountPlanPanel').hidden=true});
fetch('api/auth/status').then(r=>r.json()).then(d=>{$('loggedInUser').value=(d.username||'').toUpperCase();if(d.authenticated){location.replace('./');return}$('submit').disabled=false}).catch(()=>{$('feedback').textContent='Unable to connect. Refresh to retry.'});
$('loginForm').onsubmit=async e=>{e.preventDefault();if(busy)return;if(signup&&$('password').value!==$('confirmPassword').value){$('feedback').textContent='Passwords do not match.';return}busy=true;$('submit').disabled=true;$('feedback').textContent='';try{const body={username:$('username').value,password:$('password').value};if(signup)body.accountType=$('accountType').value;const r=await fetch(signup?'api/auth/signup':'api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error);location.replace('./')}catch(err){$('feedback').textContent=err.message;}finally{busy=false;$('submit').disabled=false}};
